"""Small, reproducible AMD64 overlapping-CFG checks (not semantic tests)."""

import io
from types import SimpleNamespace
import unittest

import angr

from extractor.binary_cfg import _walk_function
from extractor.cfg_blocks import (
    ordered_instruction_records,
    successor_index,
    validate_block_partition,
)


class GeneratedAmd64CfgTests(unittest.TestCase):
    def test_overlapping_decodes_and_shared_tails(self):
        # JE selects either MOV EAX, imm32 or a NOP inside that immediate.
        # Both streams reach the same tail; all generated bytes are nonfaulting.
        # The Cartesian product is the complete, replayable sample budget.
        entry = 0x400000
        for prefix in range(3):
            for tail in range(1, 4):
                with self.subTest(prefix=prefix, tail=tail):
                    branch = entry + prefix
                    long_start = branch + 2
                    short_start = branch + 4
                    tail_start = branch + 7
                    code = b"\x90" * prefix + b"\x74\x02\xb8" + b"\x90" * 4
                    code += b"\x90" * tail + b"\xc3"
                    project = angr.Project(
                        io.BytesIO(code),
                        main_opts={
                            "backend": "blob",
                            "arch": "amd64",
                            "base_addr": entry,
                            "entry_point": entry,
                        },
                        auto_load_libs=False,
                    )
                    pinned = SimpleNamespace(project=project, manifest={})
                    blocks, calls, indirect = _walk_function(
                        pinned,
                        root_name="generated",
                        root={"address": entry, "size": len(code)},
                        jump_tables={},
                    )
                    self.assertEqual(calls, [])
                    self.assertEqual(indirect, set())
                    expected_starts = set(range(entry, branch + 1))
                    expected_starts.add(long_start)
                    expected_starts |= set(range(short_start, entry + len(code)))
                    expected_bytes = {
                        address: code[address - entry : address - entry + 1].hex()
                        for address in expected_starts
                    }
                    expected_bytes[branch] = "7402"
                    expected_bytes[long_start] = "b890909090"
                    self.assertEqual(
                        {
                            item["address"]: item["bytes"]
                            for item in ordered_instruction_records(blocks)
                        },
                        expected_bytes,
                    )
                    graph = {
                        entry: {long_start, short_start},
                        long_start: set(),
                        short_start: set(),
                    }
                    self.assertEqual(
                        {b["address"]: set(b["successors"]) for b in blocks},
                        graph,
                    )
                    expected_successors = {
                        address: () for address in expected_starts
                    }
                    for address in range(entry, branch + 1):
                        expected_successors[address] = (long_start, short_start)
                    self.assertEqual(successor_index(blocks), expected_successors)

                    # Split one stream at the shared tail, leaving the other
                    # intact. Its shared instructions inherit the union of
                    # both blocks' successors, regardless of block ordering.
                    split_at = tail_start + 1
                    split_blocks = []
                    for block in blocks:
                        if block["address"] == long_start:
                            before = [
                                i for i in block["instructions"]
                                if i["address"] < split_at
                            ]
                            after = [
                                i for i in block["instructions"]
                                if i["address"] >= split_at
                            ]
                            split_blocks.extend(
                                [
                                    {
                                        "address": long_start,
                                        "size": split_at - long_start,
                                        "instructions": before,
                                        "successors": [split_at],
                                    },
                                    {
                                        "address": split_at,
                                        "size": entry + len(code) - split_at,
                                        "instructions": after,
                                        "successors": [],
                                    },
                                ]
                            )
                        else:
                            split_blocks.append(block)
                    split_expected = dict(expected_successors)
                    split_expected[long_start] = (split_at,)
                    split_expected[tail_start] = (split_at,)
                    reversed_blocks = [
                        split_blocks[0], *reversed(split_blocks[1:])
                    ]
                    for ordered in (split_blocks, reversed_blocks):
                        validate_block_partition(
                            root_name="generated",
                            entry=entry,
                            extent_end=entry + len(code),
                            blocks=ordered,
                        )
                        self.assertEqual(
                            {
                                item["address"]: item["bytes"]
                                for item in ordered_instruction_records(ordered)
                            },
                            expected_bytes,
                        )
                        self.assertEqual(successor_index(ordered), split_expected)


if __name__ == "__main__":
    unittest.main()
